# ---------- App content ----------
st.markdown(f'<div class="logo-wrap"><img src="data:image/png;base64,{LOGO_B64}"></div>', unsafe_allow_html=True)
st.markdown('<h1>QR Code <span class="accent">Generator</span></h1>', unsafe_allow_html=True)
st.markdown('<p class="subtitle">Turn any text or link into a scannable QR code instantly</p>', unsafe_allow_html=True)

data = st.text_input("", placeholder="Enter text or a link here...")

col1, col2 = st.columns(2)
with col1:
    fill_color = st.color_picker("QR color", "#E63946")
with col2:
    back_color = st.color_picker("Background", "#ffffff")

generate = st.button("\u2728 Generate QR Code")

if generate:
    if data.strip() == "":
        st.warning("Please enter some text or a link first.")
    else:
        qr = qrcode.QRCode(box_size=10, border=2)
        qr.add_data(data)
        qr.make(fit=True)
        img = qr.make_image(fill_color=fill_color, back_color=back_color)

        buf = BytesIO()
        img.save(buf, format="PNG")
        buf.seek(0)

        st.markdown('<div class="qr-frame">', unsafe_allow_html=True)
        st.image(buf, width=280)
        st.markdown('</div>', unsafe_allow_html=True)

        buf.seek(0)
        st.download_button(
            label="\u2b07 Download QR Code",
            data=buf,
            file_name="qr_code.png",
            mime="image/png",
        )
        st.success("QR code generated!")